# Code generated by Claude
"""Automatic neck source: aims the camera neck without operator input.

It looks ahead while the base is driving and frames the scene once each time the base comes to rest, then holds still. The eagle camera is a policy
input, so while anything is recorded its behaviour must be the same in every run and must not follow the arms (a following neck is a feedback
loop with the policy). Settings: robot_specs.NECK_AUTO_SPECS.

    source = make_neck_auto_source(model, data, teleop_source, keyboard_source, points_fn=framing_points, recording=False)

Behavior while active (mode "teleop": the teleop source is on; "always": always):
  * base driving (commanded Twist above the thresholds): the neck goes to the drive pose (looks ahead, 30 degrees down)
    and stays there
  * base at rest (after resume_delay if it was driving): ONE framing solve (src/neck_framing.frame_points, the same solve as F7 and the staging
    NECK stage) of the task points when the scene has a task (points_fn, as F7 does), else of both hands' points; the neck then holds that pose
    until the base drives again. Becoming active at rest (teleop engaged) counts as coming to rest.
  * only if specs["follow"] is True and nothing is being recorded (`recording` False): instead of the one solve, every follow_period seconds
    the hands' points are framed (local search from the current neck goal) and a command is sent if the targets moved more than the deadband.
    Off by default. Never on while a replayable recording is being written.
  * a neck key press (the keyboard source records its time) pauses all of this for pause_after_key seconds, so the
    keyboard always wins (the keys themselves are disabled while recording, see src/keyboard_source.py)
The loop's neck speed limit smooths whatever this sends. It only produces neck commands (exempt from exclusivity).
"""

import numpy as np

from src import robot_specs
from src.neck_framing import frame_points


def make_neck_auto_source(model, data, teleop, keyboard, specs=robot_specs.NECK_AUTO_SPECS, neck_specs=robot_specs.NECK_SPECS, points_fn=None, recording=False):
    """Create the automatic neck source.

    Args:
        model (mujoco.MjModel): The robot model.
        data (mujoco.MjData): The simulation state. Read for the positions of
            the hand bodies "openarm_<side>_hand_tcp" and "openarm_<side>_hand"
            (tool centre point, TCP) of both arms.
        teleop (dict | None): The teleop source, whose ["state"]["on"] tells
            whether the arms are on the webcam operator. None if there is no
            teleoperation.
        keyboard (dict): The keyboard source, whose ["state"]["neck_active_t"]
            holds the simulated time of the last neck key press.
        specs (dict): Behavior settings. Defaults to
            robot_specs.NECK_AUTO_SPECS, whose keys are
            "mode" ("teleop": active only while `teleop` is on; "always";
              any other value, such as "off", never active),
            "follow" (bool; True follows the hands with a framing every "follow_period" seconds, False frames once per stop; ignored
              while `recording`),
            "follow_period" (seconds between framing updates, follow only),
            "deadband" (radians; smaller changes are not sent, follow only),
            "pause_after_key" (seconds the keyboard keeps the neck after a neck
              key press),
            "drive_lin" (metres per second) and "drive_ang" (radians per
              second): the base counts as driving above these commanded speeds,
            "resume_delay" (seconds at rest, after driving, before framing).
        neck_specs (dict): Neck settings. Defaults to robot_specs.NECK_SPECS.
            Uses "active_joints" (joint names) and "drive_pose" (the joint
            angles in radians for looking ahead, in the order of
            "active_joints").
        points_fn (Callable | None): points_fn(model, data) -> {name: world point}, the task points to frame (as for F7). None, or an
            empty result (no task in the scene), frames both hands' tool centre points and hand origins. Defaults to None.
        recording (bool): True while a replayable recording is being written: the neck never follows, whatever specs["follow"]
            says. Defaults to False.

    Returns:
        dict: The source, with these keys:
            "name" (str): "neck_auto".
            "step" (Callable[[dict], list[dict]]): Takes the observation and
                returns neck commands (see step() inside this function).
            "state" (dict): "looking_ahead" (bool, the neck was sent to the
                drive pose and the base has not been at rest long enough),
                "stopped_since" (float | None, simulated time at which the base
                came to rest), "framed" (bool, the one framing of this rest
                period has been made), "last_follow" (float, simulated time of
                the last framing update) and "last_report" (the report from the
                last framing, or None).
    """
    st = {"looking_ahead": False, "stopped_since": None, "framed": False, "last_follow": -1e9, "last_report": None}
    follow = bool(specs.get("follow", False)) and not recording
    drive = dict(zip(neck_specs["active_joints"], neck_specs["drive_pose"]))
    sides = [s for s in ("left", "right")]

    def active():
        """Return whether the automatic neck behavior is on, from specs["mode"] and the teleop state."""
        if specs["mode"] == "always":
            return True
        return specs["mode"] == "teleop" and teleop is not None and teleop["state"]["on"]

    def step(obs):
        """Return the neck command for this tick, if any.

        Does nothing (and forgets the driving state) while inactive, and for
        specs["pause_after_key"] seconds after a neck key press. While the
        applied base command is above the drive thresholds it sends the drive
        pose once. Once the base has been at rest for specs["resume_delay"]
        seconds (only if it was driving) it frames the points ONCE and then
        holds until the base drives again; with specs["follow"] (and no
        recording) it instead frames the points at most every
        specs["follow_period"] seconds. Updates the source's state
        dictionary `st`.

        Args:
            obs (dict): Observation from the control loop. Uses:
                "time" (float): Simulated time in seconds.
                "applied" (dict): "twist" (linear speed in metres per second,
                  yaw rate in radians per second) and "neck_goal" ({joint name:
                  radians}).

        Returns:
            list[dict]: Empty, or one command {"mode": "neck", "neck_targets":
            {joint name: radians}}: the drive pose, the one framing of a rest
            period, or (follow) the framing result when some joint moves by at
            least specs["deadband"] radians.
        """
        if not active():
            st["looking_ahead"], st["stopped_since"], st["framed"] = False, None, False
            return []
        t = obs["time"]
        if t - keyboard["state"].get("neck_active_t", -1e9) < specs["pause_after_key"]:
            return []
        lin, ang = obs["applied"]["twist"]
        if abs(lin) > specs["drive_lin"] or abs(ang) > specs["drive_ang"]:
            st["stopped_since"], st["framed"] = None, False
            if not st["looking_ahead"]:
                st["looking_ahead"] = True
                return [{"mode": "neck", "neck_targets": dict(drive)}]
            return []
        if st["stopped_since"] is None:
            st["stopped_since"] = t
        if st["looking_ahead"] and t - st["stopped_since"] < specs["resume_delay"]:
            return []
        st["looking_ahead"] = False
        points = points_fn(model, data) if points_fn is not None else None
        if not points:
            points = {}
            for side in sides:
                points[f"{side}_tcp"] = data.body(f"openarm_{side}_hand_tcp").xpos.copy()
                points[f"{side}_hand"] = data.body(f"openarm_{side}_hand").xpos.copy()
        if not follow:
            if st["framed"]:
                return []                                     # framed once for this rest period: hold
            st["framed"], st["last_follow"] = True, t
            targets, report = frame_points(model, data, points, neck_specs=neck_specs)
            st["last_report"] = report
            return [{"mode": "neck", "neck_targets": targets}]
        if t - st["last_follow"] < specs["follow_period"]:
            return []
        st["last_follow"] = t
        goal = obs["applied"]["neck_goal"]
        start = np.array([goal[n] for n in neck_specs["active_joints"]])
        targets, report = frame_points(model, data, points, {}, neck_specs=neck_specs, start=start, local=True)
        st["last_report"] = report
        if max(abs(targets[n] - goal[n]) for n in targets) < specs["deadband"]:
            return []
        return [{"mode": "neck", "neck_targets": targets}]

    return {"name": "neck_auto", "step": step, "state": st}
